// ---------- src/lib/util.js ----------
const __lib_util = (() => {
  const module = { exports: {} };
/**
 * Small, dependency-free helpers shared by every Code node.
 * This file is inlined into n8n Code nodes by scripts/build-workflows.js,
 * so it must not require anything outside src/lib.
 */

const NAMED_ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '–', mdash: '—',
  lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”', hellip: '…', bull: '•', middot: '·',
  copy: '©', reg: '®', trade: '™', eacute: 'é', aacute: 'á', iacute: 'í', oacute: 'ó',
  uacute: 'ú', ntilde: 'ñ', uuml: 'ü', ouml: 'ö', auml: 'ä', ccedil: 'ç', deg: '°',
  euro: '€', pound: '£', yen: '¥', times: '×', frac12: '½', rarr: '→', larr: '←',
};

function decodeEntities(str) {
  if (!str) return '';
  return String(str).replace(/&(#x[0-9a-f]+|#\d+|[a-z][a-z0-9]*);/gi, (m, code) => {
    if (code[0] === '#') {
      const n = code[1] === 'x' || code[1] === 'X' ? parseInt(code.slice(2), 16) : parseInt(code.slice(1), 10);
      if (!Number.isFinite(n) || n <= 0 || n > 0x10ffff) return m;
      try { return String.fromCodePoint(n); } catch (e) { return m; }
    }
    const v = NAMED_ENTITIES[code.toLowerCase()];
    return v === undefined ? m : v;
  });
}

function collapseWhitespace(str) {
  return String(str || '').replace(/[\s ​]+/g, ' ').trim();
}

/** Strip tags and decode entities, producing a single clean line of text. */
function htmlToText(html) {
  return collapseWhitespace(
    decodeEntities(
      String(html || '')
        .replace(/<br\s*\/?>/gi, ' ')
        .replace(/<[^>]+>/g, ' ')
    )
  );
}

/**
 * Minimal URL parser/resolver. n8n's Code-node sandbox (task runner) has no global `URL`, so we cannot
 * rely on it. Handles absolute, protocol-relative, root-relative and relative references.
 * @returns {{protocol:string, hostname:string, port:string, host:string, origin:string, pathname:string, search:string, hash:string, href:string}|null}
 */
function parseUrl(raw, base) {
  if (raw === undefined || raw === null) return null;
  let s = String(raw).trim();
  if (!s) return null;
  const ABS = /^([a-zA-Z][a-zA-Z0-9+.-]*):\/\/([^/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/;
  let m = s.match(ABS);
  if (!m) {
    if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(s)) return null; // mailto:, javascript:, data: ...
    const b = parseUrl(base);
    if (!b) return null;
    if (s.startsWith('//')) s = `${b.protocol}${s}`;
    else if (s.startsWith('/')) s = `${b.origin}${s}`;
    else if (s.startsWith('?')) s = `${b.origin}${b.pathname}${s}`;
    else if (s.startsWith('#')) s = `${b.origin}${b.pathname}${b.search}${s}`;
    else s = `${b.origin}${b.pathname.replace(/[^/]*$/, '')}${s}`;
    m = s.match(ABS);
    if (!m) return null;
  }
  const protocol = m[1].toLowerCase() + ':';
  const authority = m[2].replace(/^.*@/, '');
  const hm = authority.match(/^(\[[^\]]+\]|[^:]*)(?::(\d*))?$/);
  if (!hm || !hm[1]) return null;
  const hostname = hm[1].toLowerCase();
  const defaultPort = (protocol === 'https:' && hm[2] === '443') || (protocol === 'http:' && hm[2] === '80');
  const port = hm[2] && !defaultPort ? hm[2] : '';
  // normalise dot segments
  const segs = [];
  for (const seg of (m[3] || '/').split('/')) {
    if (seg === '..') { if (segs.length > 1) segs.pop(); } else if (seg !== '.') segs.push(seg);
  }
  let pathname = segs.join('/');
  if (!pathname.startsWith('/')) pathname = '/' + pathname;
  const search = m[4] && m[4] !== '?' ? m[4] : '';
  const hash = m[5] && m[5] !== '#' ? m[5] : '';
  const host = hostname + (port ? `:${port}` : '');
  const origin = `${protocol}//${host}`;
  return { protocol, hostname, port, host, origin, pathname, search, hash, href: origin + pathname + search + hash };
}

/** Lower-cased host, no fragment, no query, no trailing slash. Path case is preserved. */
function normalizeUrl(raw, base) {
  if (!raw) return null;
  const u = parseUrl(raw, base);
  if (!u || !/^https?:$/.test(u.protocol)) return null;
  const protocol = /(^|\.)placidway\.com$/.test(u.hostname) ? 'https:' : u.protocol; // the live site is HTTPS-only
  return `${protocol}//${u.host}${u.pathname.replace(/\/+$/, '')}`;
}

/** Map a PlacidWay URL to a stable content key such as "article:4617" (slug/subdomain independent). */
const CONTENT_PATTERNS = [
  { type: 'article', re: /\/article\/(\d+)(?:\/|$)/i },
  { type: 'package', re: /\/package\/(\d+)(?:\/|$)/i },
  { type: 'answer', re: /\/answer-detail\/(\d+)(?:\/|$)/i },
];

function contentKeyFromUrl(url, extraHosts) {
  if (!url) return null;
  const parsed = parseUrl(url);
  if (!parsed) return null;
  const host = parsed.hostname;
  const allowed = /(^|\.)placidway\.com$/.test(host) || (extraHosts || []).includes(host);
  if (!allowed) return null;
  for (const p of CONTENT_PATTERNS) {
    const m = url.match(p.re);
    if (m) return { type: p.type, id: m[1], key: `${p.type}:${m[1]}` };
  }
  return null;
}

/** Postgres parameters are passed as one base64 JSON blob: immune to the comma-splitting of
 *  "Query Parameters" and to SQL injection; decoded in SQL with convert_from(decode($1,'base64'),'UTF8')::jsonb */
function toB64Json(obj) {
  const json = JSON.stringify(obj);
  if (typeof Buffer !== 'undefined') return Buffer.from(json, 'utf8').toString('base64');
  return btoa(unescape(encodeURIComponent(json)));
}

function escapeTelegramHtml(str) {
  return String(str == null ? '' : str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function escapeAttr(str) {
  return escapeTelegramHtml(str).replace(/"/g, '&quot;');
}

function truncate(str, max) {
  const s = String(str || '');
  const chars = [...s];
  if (chars.length <= max) return s;
  return chars.slice(0, Math.max(0, max - 1)).join('').trimEnd() + '…';
}

/** Character count as Facebook / humans see it (code points, not UTF-16 units). */
function charLength(str) {
  return [...String(str || '')].length;
}

/** Lower-case, unify quotes/dashes, strip punctuation except digits/letters, collapse spaces. */
function normalizeForMatch(str) {
  return collapseWhitespace(
    String(str || '')
      .toLowerCase()
      .replace(/[‘’`´]/g, "'")
      .replace(/[“”]/g, '"')
      .replace(/[‐‑‒–—―]/g, '-')
      .replace(/(\d),(\d{3})/g, '$1$2')
      .replace(/[^a-z0-9$%.\-' ]+/g, ' ')
      .replace(/(\D)\.|\.(\D|$)/g, '$1 $2')
  );
}

/** Pulls the provider's own error text out of n8n's wrapped messages like 400 - "{\"error\":{\"message\":\"...\"}}". */
function innerApiMessage(error) {
  const flat = typeof error === 'string' ? error : JSON.stringify(error || {});
  const msgs = [...flat.matchAll(/\\*"message\\*"\s*:\s*\\*"((?:[^"\\]|\\[^"])*)/g)]
    .map((m) => m[1].replace(/\\+$/, '').replace(/\\+(["/])/g, '$1'))
    .filter((m) => m && !/^\d{3} - $/.test(m));
  return msgs.length ? msgs[msgs.length - 1] : null;
}

function safeJsonParse(text) {
  if (text && typeof text === 'object') return text;
  if (typeof text !== 'string') return null;
  let t = text.trim();
  const fence = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fence) t = fence[1];
  try { return JSON.parse(t); } catch (e) { /* fall through */ }
  const first = t.indexOf('{');
  const last = t.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(t.slice(first, last + 1)); } catch (e) { return null; }
  }
  return null;
}

module.exports = {
  parseUrl, decodeEntities, collapseWhitespace, htmlToText, normalizeUrl, contentKeyFromUrl, toB64Json,
  escapeTelegramHtml, escapeAttr, truncate, charLength, normalizeForMatch, safeJsonParse, innerApiMessage,
};

  return module.exports;
})();

// ---------- src/lib/publish.js ----------
const __lib_publish = (() => {
  const module = { exports: {} };

/** Offset (minutes) of a timezone at a given instant, using only Intl (no Luxon needed). */
function tzOffsetMinutes(date, timeZone) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',
  }).formatToParts(date).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
  const asUtc = Date.UTC(+parts.year, +parts.month - 1, +parts.day, +parts.hour, +parts.minute, +parts.second);
  return Math.round((asUtc - date.getTime()) / 60000);
}

function localDateParts(date, timeZone) {
  const p = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
  const [y, m, d] = p.split('-').map(Number);
  return { y, m, d };
}

/**
 * Next occurrence of HH:MM in `timeZone` that is at least `minLeadMinutes` in the future.
 * Facebook requires scheduled_publish_time between 10 minutes and 30 days ahead; we keep a 15 minute margin.
 */
function nextScheduleTime(nowIso, hhmm, timeZone, minLeadMinutes = 15) {
  const now = new Date(nowIso);
  const [hh, mm] = hhmm.split(':').map(Number);
  for (let addDays = 0; addDays < 3; addDays++) {
    const base = new Date(now.getTime() + addDays * 86400000);
    const { y, m, d } = localDateParts(base, timeZone);
    let guess = Date.UTC(y, m - 1, d, hh, mm, 0);
    guess -= tzOffsetMinutes(new Date(guess), timeZone) * 60000;
    // second pass corrects DST transitions
    const corrected = Date.UTC(y, m - 1, d, hh, mm, 0) - tzOffsetMinutes(new Date(guess), timeZone) * 60000;
    if (corrected >= now.getTime() + minLeadMinutes * 60000) return new Date(corrected);
  }
  return new Date(now.getTime() + 60 * 60000);
}

function localDayString(nowIso, timeZone) {
  const { y, m, d } = localDateParts(new Date(nowIso), timeZone);
  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

/** Instagram only accepts JPEG via image_url: ask PlacidWay's Cloudflare image endpoint for a JPEG rendition. */
function instagramImage(url) {
  const m = String(url).match(/^(https:\/\/[^/]+\/cdn-cgi\/image\/)([^/]+)\/(.+)$/);
  if (!m) return url;
  const opts = m[2].split(',').filter((o) => !/^format=/.test(o)).concat('format=jpeg').join(',');
  return `${m[1]}${opts}/${m[3]}`;
}

/**
 * Builds the Facebook Graph API calls for this post.
 *  - photo post: POST /{page-id}/photos  {url, caption}  -> image is uploaded by Facebook from the URL
 *  - link post:  POST /{page-id}/feed    {message, link} -> Facebook renders the page's og:image as a preview
 * Scheduling uses published=false + scheduled_publish_time (unix seconds).
 */
function buildPublishPlan({ post, content, cfg, nowIso }) {
  const scheduled = cfg.publish_strategy === 'schedule';
  const when = scheduled ? nextScheduleTime(nowIso, cfg.schedule_time, cfg.timezone) : null;
  const scheduleFields = scheduled ? { published: false, scheduled_publish_time: Math.floor(when.getTime() / 1000) } : { published: true };
  const base = `${cfg.fb_graph_base}/${cfg.fb_page_id || 'PAGE_ID'}`;
  const feed = { endpoint: 'feed', url: `${base}/feed`, body: { message: post.text, link: content.url, ...scheduleFields } };
  const usePhoto = cfg.post_format === 'photo' && !!content.image_url;
  const photo = usePhoto ? { endpoint: 'photos', url: `${base}/photos`, body: { url: content.image_url, caption: post.text, ...scheduleFields } } : null;
  // Instagram (optional cross-post): JPEG image required, links in captions are not clickable.
  let instagram = null;
  if (cfg.ig_user_id && content.image_url) {
    const caption = [post.text_before_link, '', `🔗 Read the full ${content.type === 'answer' ? 'answer' : content.type} on ${cfg.brand_name}.com`, '', post.hashtags.join(' '), cfg.disclaimer].filter((x) => x !== undefined && x !== null).join('\n').trim();
    instagram = {
      create_url: `${cfg.fb_graph_base}/${cfg.ig_user_id}/media`,
      publish_url: `${cfg.fb_graph_base}/${cfg.ig_user_id}/media_publish`,
      body: { image_url: instagramImage(content.image_url), caption: caption.slice(0, 2200) },
    };
  }
  return {
    instagram,
    primary: photo || feed,
    fallback: photo ? feed : null, // photo upload failures (bad image) fall back to a link post
    scheduled,
    scheduled_for: when ? when.toISOString() : null,
    with_image: usePhoto || !!content.image_url, // link posts still show the og:image preview
  };
}

const TOKEN_CODES = new Set([190, 102, 463, 467]);
const PERMISSION_CODES = new Set([10, 200, 210, 220, 230, 299]);
const RATE_CODES = new Set([4, 17, 32, 341, 368, 613]);
const TRANSIENT_CODES = new Set([1, 2]);

/** Classifies a Graph API error from a response body or an n8n error object (code first, text second). */
function classifyGraphError(input) {
  let body = input;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { raw: body }; } }
  const flat = JSON.stringify(body || {});
  const fb = (body && body.error && typeof body.error === 'object' && body.error.code !== undefined) ? body.error : null;
  // n8n wraps the Graph response as an escaped JSON string inside message/description
  const num = (re) => { const m = flat.match(re); return m ? Number(m[1]) : null; };
  const code = fb ? Number(fb.code) : num(/\\*"code\\*"\s*:\s*(\d+)/);
  const sub = fb ? fb.error_subcode : num(/\\*"error_subcode\\*"\s*:\s*(\d+)/);
  // innermost "message" is the Graph API's own text (outer ones are n8n's "400 - ..." wrappers)
  const msgs = [...flat.matchAll(/\\*"message\\*"\s*:\s*\\*"((?:[^"\\]|\\[^"])*)/g)].map((m) => m[1].replace(/\\+$/, '').replace(/\\+(["/])/g, '$1')).filter((m) => m && !/^\d{3} - $/.test(m));
  const embedded = msgs.length ? msgs[msgs.length - 1] : null;
  const message = (fb && fb.message) || embedded || (body && body.message) || flat.slice(0, 300);
  const out = (c, retryable, hint) => ({ code: c, retryable, graph_code: code, graph_subcode: sub || null, message, hint });

